//! Berlin, because the analyzer also runs on blocks before London and Shanghai.

use alloy::sol;

pub(super) const LEG_RUNNER_BYTECODE: &[u8] = &alloy::primitives::hex!(
    ""
);

sol! {
    #[derive(Debug, PartialEq, Eq)]
    struct LegResult {
        uint256 bought;
        bool transferOk;
        uint256 transferSent;
        uint256 transferReceived;
        uint256 transferGas;
        bool approveOk;
        bool sellOk;
        uint256 sellSent;
        uint256 sellArrived;
        uint256 sellGas;
        int256 walletDrift;
        bytes transferRevert;
        bytes sellRevert;
    }

    function record(address token) external;
    function legs(address token, address pool, address wallet) external returns (LegResult memory r);

}
